#include "engine.hpp"
#include <iostream>
using namespace uaa;
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(int argc,char** argv){try{
 check(argc==3,"Expected data and temporary directory");Engine e(argv[1],argv[2]);check(e.createBase("Manufacturing",50,14).ok,"Create fresh base");
 for(const auto& id:{"iron","plastics","electronics","glass"}){check(e.state["stock"][id]==100,"New game starts with one hundred of each material");e.state["stock"][id]=0;}
 auto quote=e.manufactureQuote("weapons","pistol",2);check(!quote["ok"].get<bool>()&&quote["cost"]==900&&quote["hours"]==18,"Quote complete two-unit recipe");for(const auto& m:quote["materials"])check(m["required"]==2&&m["have"]==0&&m["missing"]==2,"Display full missing quantities");
 auto before=e.state;check(!e.manufacture("weapons","pistol",2).ok&&e.state==before,"Missing materials must not create a partial order");
 check(e.trade("materials","iron",true).ok&&e.trade("materials","plastics",true).ok,"Existing storage market supplies materials");e.advance(e.state["tradeFlights"].back()["arrival"].get<double>()-e.state["hours"].get<double>());before=e.state;check(!e.manufacture("weapons","pistol",2).ok&&e.state==before,"Resources for one unit must not start a two-unit order");
 check(e.trade("materials","iron",true).ok&&e.trade("materials","plastics",true).ok,"Purchase remaining materials");e.advance(e.state["tradeFlights"].back()["arrival"].get<double>()-e.state["hours"].get<double>());auto money=e.state["money"];e.state["money"]=899;before=e.state;check(!e.manufacture("weapons","pistol",2).ok&&e.state==before,"Insufficient funds must preserve all materials");e.state["money"]=money;
 check(e.manufacture("weapons","pistol",2).ok&&e.state["production"].size()==2,"Queue exact requested quantity");check(e.state["money"].get<long long>()==money.get<long long>()-900&&e.state["stock"]["iron"]==0&&e.state["stock"]["plastics"]==0,"Debit recipe and funds once");
 for(const auto& order:e.state["production"])check(order["started"]==e.state["hours"]&&order["ready"].get<double>()==e.state["hours"].get<double>()+18.&&order["group"]=="weapons","Persist timestamps for progress display");check(e.assignTechnician("weapons","pistol",6,true).ok&&e.assignTechnician("weapons","pistol",7,true).ok,"Assign two production technicians");int stock=e.state["stock"]["pistol"];e.advance(9);check(e.state["stock"]["pistol"]==stock,"Work remains in progress at halfway point");e.save(1);
 Engine loaded(argv[1],argv[2]);check(loaded.load(1).ok,"Load unfinished production");loaded.advance(9);check(loaded.state["stock"]["pistol"]==stock+2&&loaded.state["production"].empty(),"Completed items reach storage after reload");
 before=e.state;for(int count:{-1,0,101})check(!e.manufacture("weapons","pistol",count).ok,"Reject invalid quantities");check(e.state==before,"Invalid quantities are transactional");check(!e.manufacture("units","soldier").ok,"Personnel cannot be manufactured");
 e.state["money"]=100000000;quote=e.manufactureQuote("units","fighter",2);for(const auto& m:quote["materials"])e.state["stock"][m["id"].get<std::string>()]=m["required"];
 before=e.state;check(!e.manufacture("units","fighter",3).ok&&e.state==before,"Whole aircraft order is checked before mutation");check(e.manufacture("units","fighter",2).ok,"Queue available fighter capacity");check(e.assignTechnician("units","fighter",8,true).ok&&e.assignTechnician("units","fighter",9,true).ok,"Assign aircraft technicians");auto fleet=e.state["craft"].size();e.advance(quote["hours"]);check(e.state["craft"].size()==fleet+2,"Produced aircraft enter the hangar");before=e.state;check(!e.manufacture("units","fighter").ok&&e.state==before,"Full hangar rejects further aircraft");
 e.save(2);auto invalid=readJson(e.userDir/"save-2.json");invalid["production"].push_back({{"id","pistol"},{"started",20.},{"ready",10.}});writeJson(e.userDir/"save-3.json",invalid);before=loaded.state;check(!loaded.load(3).ok&&loaded.state==before,"Malformed production progress cannot replace the campaign");
 Engine teams(argv[1],fs::path(argv[2])/"teams");teams.createBase("Teams",50,14);teams.state["stock"]["iron"]=3;teams.state["stock"]["plastics"]=3;check(teams.manufacture("weapons","pistol",3).ok,"Queue work before assigning technicians");int initial=teams.state["stock"]["pistol"];teams.advance(12);check(teams.state["stock"]["pistol"]==initial,"Production waits for assigned technicians");check(teams.assignTechnician("weapons","pistol",6,true).ok,"Assign first technician");auto snapshot=teams.state;check(!teams.assignTechnician("weapons","rifle",6,true).ok&&teams.state==snapshot,"Technician cannot join two teams");check(!teams.assignTechnician("weapons","pistol",0,true).ok,"Pilot cannot perform technician work");teams.advance(18);check(teams.state["stock"]["pistol"]==initial+1&&teams.state["production"].size()==2,"One technician completes one simultaneous unit");check(teams.productionProgress("weapons","pistol")["completed"]==1&&teams.productionProgress("weapons","pistol")["remaining"]==2,"Visible summary decrements remaining pieces");check(teams.state.value("pendingProductionCompletions",0)==1,"Each finished unit creates a persistent announcement");check(teams.assignTechnician("weapons","pistol",7,true).ok,"Assign second technician");teams.save(1);Engine reload(argv[1],fs::path(argv[2])/"teams");check(reload.load(1).ok&&reload.productionTeam("weapons","pistol").size()==2,"Production team survives reload");check(reload.state.value("pendingProductionCompletions",0)==1,"Unacknowledged completion survives reload");reload.advance(18);check(reload.state.value("pendingProductionCompletions",0)==3&&reload.state["production"].empty(),"Remaining count reaches zero and all finished units are announced");check(reload.state["stock"]["pistol"]==initial+3&&reload.technicianProject(6).empty(),"Two technicians finish two remaining units and become available");
 check(reload.productionProgress("weapons","pistol")["progress"]==1.&&reload.productionProgress("weapons","pistol")["completed"]==3,"Completed batch retains one hundred percent progress");
 Engine queued(argv[1],fs::path(argv[2])/"queue");queued.createBase("Queue",50,14);for(auto material:{"iron","plastics","electronics","glass"})queued.state["stock"][material]=500;check(queued.manufacture("weapons","pistol",1).ok&&queued.manufacture("weapons","rifle",1).ok,"Queue two different work designs");check(queued.assignTechnician("weapons","pistol",6,true).ok,"Staff first job");auto schedule=queued.productionSchedule();double rifleHours=queued.manufactureQuote("weapons","rifle",1)["hours"];check(schedule.size()==2&&schedule[0]["finishInHours"]==18.&&schedule[1]["startInHours"]==18.&&schedule[1]["finishInHours"]==18.+rifleHours,"Queue ETA includes waiting and remaining work");Engine jump(argv[1],fs::path(argv[2])/"jump");jump.state=queued.state;jump.advance(18+rifleHours);check(jump.state["production"].empty()&&jump.productionProgress("weapons","rifle")["completed"]==1,"Large time advance carries technicians and unused time into the next item");queued.advance(18);check(queued.productionSchedule()[0]["finishInHours"]==rifleHours,"ETA counts down after previous item completes");check(queued.productionTeam("weapons","rifle")==Json::array({6})&&queued.state["production"].size()==1,"Released technician moves to first waiting job");queued.save(1);Engine nextJob(argv[1],fs::path(argv[2])/"queue");check(nextJob.load(1).ok,"Work queue and transferred staffing survive reload");nextJob.advance(nextJob.manufactureQuote("weapons","rifle",1)["hours"]);check(nextJob.state["production"].empty()&&nextJob.productionProgress("weapons","rifle")["progress"]==1.,"Second queued job completes with visible final progress");
 std::cout<<"PASS: fresh-stock manufacturing, visible recipe, bulk atomicity, storage purchase route, timed completion, reload, aircraft delivery/capacity and save validation\n";return 0;
 }catch(const std::exception& error){std::cerr<<"FAIL: "<<error.what()<<"\n";return 1;}}
